// #edb46e (9b0df2d0d928981d43edb46e) «iOS - כפתור «מפת ההשפעה» במסך הבית פותח הודעה «עדיין בפיתוח» במקום את מפת ההשפעה» — עבר QA 21.10.2026.
// מה רצוי: F-99 AC2/AC5 + Figma S-01: кнопка «מפת ההשפעה» на главной открывает карту влияния (כמו ב«המסע שלי»), а не окно «בפיתוח».
// Коммент программиста (c53d0c8): кнопка открывает «המסע שלי» с прокруткой к секции «מפת השפעה»; вход через таб — экран сверху.
// Факт 21.10: кнопка → «המסע שלי» на секции карты; таб — сверху; повтор работает (2110-9b0df2d0-map.png).
// Кейс: .qa/tests/impact-map/IM-04-home-button-opens-map.md.
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, tapText } from '../../helpers/ui.ts';
import { shown } from '../_lib/app-0710.ts';
import { goHome, button, nodes } from '../_lib/readiness-1910.ts';
import { fullyOnScreen } from '../_lib/app-2110.ts';

const SECTION = 'מפת השפעה';
const OLD_DIALOG = 'עדיין בפיתוח';

async function sectionTitle() {
  const n = (await nodes()).find((x) => x.label === SECTION && /StaticText|TextView|Other/.test(x.type));
  return n ?? null;
}

describe('21.10 — кнопка «מפת ההשפעה» на главной (#edb46e)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('IM-04 «מפת ההשפעה» на главной → «המסע שלי» на секции «מפת השפעה» (видна, с «אני»/людьми или пустым состоянием и «הזמנת אדם להתחזק»), без «…עדיין בפיתוח»; таб «המסע שלי» — сверху; повторный тап работает #edb46e #9b0df2d0 F-99 AC2 AC4 AC5 @prod-safe', async () => {
    for (let round = 1; round <= 2; round++) {
      await goHome();
      await (await button('מפת ההשפעה')).click();
      await driver.waitUntil(async () => (await shown(byTextContains(OLD_DIALOG))) || (await shown(byText(SECTION))),
        { timeout: 15000, timeoutMsg: `раунд ${round}: после «מפת ההשפעה» нет ни секции карты, ни окна` });
      expect(await shown(byTextContains(OLD_DIALOG))).toBe(false);
      // Секция карты на экране (прокрутка остановилась на ней), это экран «המסע שלי».
      expect(await fullyOnScreen((await byText(SECTION)) as unknown as WebdriverIO.Element)).toBe(true);
      const labels = (await nodes()).map((n) => n.label).join('\n');
      // F-99 AC5: видимая кнопка приглашения; AC2/AC4: «אני» в центре или пустое состояние.
      expect(labels).toContain('הזמנת אדם להתחזק');
      expect(/אני|אין עדיין אנשים במפה/.test(labels)).toBe(true);
      console.log(`[IM-04] раунд ${round}: секция «${SECTION}» видна, y=${(await sectionTitle())?.y}`);
    }

    // Вход через таб «המסע שלי» — экран сверху (заголовок/аватар видны, секция карты не обязана быть на экране).
    await goHome();
    await tapText('המסע שלי');
    await (await byText('המסע שלי')).waitForExist({ timeout: 20000 });
    await expect(byTextContains('דרגה')).toBeExisting();
    const top = (await nodes()).find((n) => /^דרגה \d+ מתוך 10$/.test(n.label));
    expect(top && top.y >= 0 && top.y < 700).toBe(true);
  });
});
